// Returns every building within `radius` hops of `building` (inclusive), mapped to its hop distance.
// Returns an empty map if the building is unknown.
inline std::map<std::string, int> neighbors_within(const std::string& building, int radius) {
    std::map<std::string, int> found;
    if (!neighbors.count(building)) return found;
    std::vector<std::string> frontier = {building};
    found[building] = 0;
    for (int depth = 1; depth <= radius && !frontier.empty(); depth++) {
        std::vector<std::string> next;
        for (const auto& b : frontier) {
            for (const auto& n : neighbors.at(b)) {
                if (found.count(n)) continue;
                found[n] = depth;
                next.push_back(n);
            }
        }
        frontier = std::move(next);
    }
    return found;
}

